list.innerHTML = posts.map((p) => {
  const preview = p.body.length > 240 ? `${p.body.slice(0, 240)}...` : p.body;
  return `
    <article class="card">
      <h3><a href="/posts/${p.id}">${escapeHtml(p.title)}</a></h3>
      <div class="meta">
        By <a href="/users/${p.authorId}">${escapeHtml(p.authorDisplayName)}</a>
        &middot; ${formatDate(p.createdAt)}
        ${isEdited(p) ? ' (edited)' : ''}
        &middot; ${p.commentCount} ${p.commentCount === 1 ? 'comment' : 'comments'}
      </div>
      <p class="post-body">${escapeHtml(preview)}</p>
    </article>
  `;
}).join('');

