list.innerHTML = comments.map((c) => {
  const isOwner = currentUser && currentUser.id === c.authorId;
  return `
    <div class="card" data-comment-id="${c.id}">
      <div class="comment-view">
        <div class="meta comment-author">${userChip(c)}<span>${formatDate(c.createdAt)}${isEdited(c) ? ' (edited)' : ''}</span></div>
        <p class="comment-body">${escapeHtml(c.body)}</p>
        ${isOwner ? `<div class="actions"><button type="button" class="btn btn-sm edit-comment-btn">Edit</button><button type="button" class="btn btn-danger btn-sm delete-comment-btn">Delete</button></div>` : ''}
      </div>
      ${isOwner ? `
        <form class="edit-comment-form" hidden>
          <div class="error edit-comment-error" hidden></div>
          <div class="form-group"><textarea class="edit-comment-textarea" maxlength="4000" required>${escapeHtml(c.body)}</textarea></div>
          <div class="actions"><button type="submit" class="btn btn-primary btn-sm">Save</button><button type="button" class="btn btn-sm cancel-edit-comment">Cancel</button></div>
        </form>
      ` : ''}
    </div>
  `;
}).join('');

